import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"55、【豐】 離下震上","description":"周易闡真 - 55、【豐】 離下震上","frontmatter":{"title":"55、【豐】 離下震上","description":"周易闡真 - 55、【豐】 離下震上"},"headers":[],"relativePath":"classics/chanzhen/056.md","filePath":"classics/chanzhen/056.md"}'),s={name:"classics/chanzhen/056.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：豐，大也。明以動，故豐。王假之，尚大也。勿憂宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎，況於鬼神乎。</p></blockquote><h1 id="_55、【豐】-離下震上" tabindex="-1">55、【豐】 離下震上 <a class="header-anchor" href="#_55、【豐】-離下震上" aria-label="Permalink to “55、【豐】 離下震上”">​</a></h1><p>初九：遇其配主，雖旬無咎，往有尚。</p><p>六二：豐其蔀，日中見鬥。往得疑疾，有孚發若，吉。</p><p>九三：豐其沛，日中見沬。折其右肱，無咎。</p><p>九四：豐其蔀，日中見鬥。遇其夷主，吉。</p><p>六五：來章，有慶譽，吉。</p><p>上六：豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雷電皆至，豐。君子以折獄致刑。</p><p>豐者，足盛也。上震雷，下離火，是雷電皆至，雷以震之，電以照之，雷電相濟，威明並行，豐之象也。</p><p>君子有見於此，知人處世間，認假棄真，以苦為樂，貪財好色，喪德敗行，作孽百端，入於昏暗不明之地，如犯罪在獄，待時受刑，原其故，皆由不知辨別真假。以是效電光之灼照，窮究性命幽深之理，分別邪正，如折獄之折。既辨其假中之真，又辨其真中之假，真知確見，不至於似是而非。法雷霆之剛烈，剿除客邪之氣，整頓精神，如致刑之致，無罪者解脫之，有罪者殺戮之，果斷直行而不至於姑息養奸。折獄者，用柔細辨，致知也；致刑者，用剛決烈，力行也。聖賢身心性命之學，致知力行兩端。知而不行，不能成道；行而不知，反誤性命。知而後行，明而後動，行以全知，動以驗明，一日克己禮，天下歸仁焉。學者若能折理如折獄之折，果行如致刑之果，何患不到富有日新，道德豐盛之地耶?</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>蔀，音剖。沬，音昧。折，食列反。闃，苦臭反。覿，音狄。</p><p>豐者，盛大也。卦德上震動，下離明，明以運動，動本於明。明動相濟，明大而動大，故謂豐。此運火防危之卦，承上漸卦而來。漸者，止而巽行，所以循序漸進，不使火候有差耳。火者，明之象，運火即運明也。明為覺察之德，能覺則有道心而神知，能察則無人心而心明。神知心明，潛修密煉，明於動而動必明，其明日增，其動日大，明動並行，修道最易，此豐之所以有亨道也。</p><p>然明動之豐雖亨，須要知進知退，能大能小，防危慮險，方能豐者長豐，亨者長亨，如王假之有勿憂之道也。假者，大也。王者，當治道豐盛之時，諸事易於尚大，大而知保，何憂其大？勿憂之道為何道?宜日中之道也。</p><p>日為離明之象。中者，無偏無倚之謂。進明豐足，火候已到，藥物已成，急宜灶底抽薪，住火停輪，當止即止，明不過用也。明不過用，進退隨時，剛柔相當，不偏不倚，未豐者能以致，已豐者能以保，更何憂其豐而又不豐乎?</p><p>初九，在豐之初，其明不大，正當致豐之時，有應同德之賢，是遇其配主矣。遇配主而彼此資益，以增其明，雖在旬初，可以無咎，其用剛往而有尚，其理可決。此剛而致豐於始也。</p><p>六二，所應非人，不但不能增明，反蔽其明，如豐其蔀，日中見鬥矣。鬥見日中，日光不勝鬥光，其明障蔽不通，以是往而運火行符，是非罔辨，其行犯難，必得疑疾矣。幸其真師在望，若知己不明，誠求他家之明，借剛濟柔，奮發精神，勇猛前進，不但無疑，而且致吉。此柔而借剛致豐也。</p><p>九三，用明太過，欲豐其明，反昧其明，如日中見沬矣。沬見日中，日光不勝星光，明傷極矣。原其故，只知用剛，不知用柔；只知用明，不知養明。其進銳者，其退速，如折其右肱，自取其敗，與人無咎。此剛而不能柔之豐也。</p><p>九四，剛居動體，有近於陰，不但不能豐明，而且有以豐蔀，如日中見鬥矣。然剛而能柔，不用其明，能養其明，是以遇其夷，主吉。夷者，視而不見，隱藏之謂。大凡真正修道之士，被褐懷玉，多隱於卑下之處，人不能識，四能遇之，彼此勸勉，養明而不用明，明自不傷，剛自不敗。此剛而能柔之豐也。</p><p>六五，柔順得中，虛心即能實腹，是以來章有慶譽也。來章者，虛室生白，神明自來也。有慶譽者，始於有作無人見，及至無為眾始知也。五在正豐之時，虛實相應，明動自然，金丹已結，正宜行無為之道，用文火以溫養。此柔而無為之豐也。</p><p>上六，柔而無知，不明大道，孤寂守靜，自滿自足，虛裝門面，入於黑暗不明之地。如有屋無人，不明於始，見兇於終，豐之極，兇之極，所謂巍巍佛堂，其中無佛者即是。此柔而頑空之豐也。</p><p>然則豐之為道，未豐須當先明後行而致豐，已豐須當住火停輪而保豐。致豐保豐，各隨其時，防危虛險，用明運火，不失之太過，不失之不及，得其中為吉歟！</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
